#!/bin/bash
cd /opt/farmwatch
mkdir -p backend/models
echo '' | base64 -d > backend/models/models.py
mkdir -p backend
echo '' | base64 -d > backend/schemas.py
mkdir -p backend/routers
echo '' | base64 -d > backend/routers/farms.py
mkdir -p backend/routers
echo '' | base64 -d > backend/routers/tasks.py
mkdir -p backend/routers
echo '' | base64 -d > backend/routers/webhook.py
mkdir -p backend/services
echo '' | base64 -d > backend/services/line_service.py
mkdir -p frontend/js
echo '' | base64 -d > frontend/js/api.js
mkdir -p frontend/js/components
echo '' | base64 -d > frontend/js/components/settings.js
mkdir -p frontend/js/components
echo '' | base64 -d > frontend/js/components/progress.js
mkdir -p frontend/js/components
echo '' | base64 -d > frontend/js/components/photo-wall.js
mkdir -p backend
echo '' | base64 -d > backend/upgrade_db.py

echo 'Restarting Docker Containers (without cache)...'
if command -v docker-compose &> /dev/null; then
    docker-compose down
    docker-compose build --no-cache
    docker-compose up -d
else
    docker compose down
    docker compose build --no-cache
    docker compose up -d
fi

echo 'Update Complete! ?'
